"""Calibration + validation workflow with an automatically generated report.

``run_validation`` works on any list of measured drives (real or synthetic):
split into calibration and validation drives, evaluate the initial model,
calibrate, evaluate again, write plots, a Markdown report and the
calibrated vehicle configuration.
"""

from __future__ import annotations

import os
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402

from evdynasim.calibration import (  # noqa: E402
    DEFAULT_PARAMS,
    CalibrationResult,
    calibrate,
    evaluate,
    simulate_drive,
)
from evdynasim.measured import MeasuredDrive, interval_to_sample_power  # noqa: E402
from evdynasim.params import ModelParams, get_value  # noqa: E402

#: parameter path -> (YAML key, factor from SI to the YAML unit)
YAML_KEYS = {
    "body.rolling_coefficient": ("vehicle", "rolling_coefficient", 1.0),
    "body.drag_coefficient": ("vehicle", "drag_coefficient", 1.0),
    "aux.base_power_w": ("auxiliaries", "base_power_kw", 1e-3),
    "aux.hvac_w_per_k": ("auxiliaries", "hvac_kw_per_k", 1e-3),
}


def write_calibrated_config(src: Path, dst: Path, p: ModelParams, keys: list[str]) -> Path:
    """Copy the YAML file, replacing calibrated values and fixing the loss-map path."""
    lines = Path(src).read_text(encoding="utf-8").splitlines()
    section = ""
    out = []
    for line in lines:
        stripped = line.strip()
        if line and not line[0].isspace() and stripped.endswith(":"):
            section = stripped[:-1]
        key = stripped.split(":")[0] if ":" in stripped else ""
        for path in keys:
            sec, yaml_key, factor = YAML_KEYS[path]
            if section == sec and key == yaml_key:
                line = f"  {yaml_key}: {get_value(p, path) * factor:.6g}    # calibrated"
        if section == "motor" and key == "loss_map_csv":
            value = stripped.split(":", 1)[1].split("#")[0].strip().strip('"')
            if value:
                rel = os.path.relpath(
                    Path(src).resolve().parent / value, Path(dst).resolve().parent
                )
                line = f'  loss_map_csv: "{Path(rel).as_posix()}"'
        out.append(line)
    header = f"# Calibrated copy of {Path(src).name}, generated by evdynasim.\n"
    dst.write_text(header + "\n".join(out) + "\n", encoding="utf-8")
    return dst


def _plot_timeseries(p0, p1, drive: MeasuredDrive, out: Path, window=(200, 700)) -> Path:
    r0, r1 = simulate_drive(p0, drive), simulate_drive(p1, drive)
    t = drive.time_s
    sel = (t >= window[0]) & (t <= window[1])
    fig, axes = plt.subplots(2, 1, figsize=(11, 6.5), sharex=True)
    axes[0].plot(t[sel], drive.speed_mps[sel] * 3.6, lw=1.2)
    axes[0].set_ylabel("Speed (km/h)")
    axes[1].plot(t[sel], drive.battery_power_w[sel] / 1e3, color="k", lw=1.0, label="measured")
    axes[1].plot(t[sel], interval_to_sample_power(r0.battery_power_w)[sel] / 1e3, lw=1.0,
                 alpha=0.8, label="initial model")  # fmt: skip
    axes[1].plot(t[sel], interval_to_sample_power(r1.battery_power_w)[sel] / 1e3, lw=1.0,
                 alpha=0.9, label="calibrated model")  # fmt: skip
    axes[1].set_ylabel("Battery power (kW)")
    axes[1].set_xlabel("Time (s)")
    axes[1].legend(loc="upper right")
    for ax in axes:
        ax.grid(True, alpha=0.3)
    fig.suptitle(f"Validation drive {drive.name} (not used for calibration)")
    fig.tight_layout()
    fig.savefig(out, dpi=140)
    plt.close(fig)
    return out


def _plot_parity(p1, drives, out: Path) -> Path:
    fig, ax = plt.subplots(figsize=(5.5, 5.5))
    lim = 0.0
    for d in drives:
        sim = interval_to_sample_power(simulate_drive(p1, d).battery_power_w) / 1e3
        ax.plot(d.battery_power_w / 1e3, sim, ".", ms=2, alpha=0.4, label=d.name)
        lim = max(lim, np.abs(sim).max(), np.abs(d.battery_power_w).max() / 1e3)
    ax.plot([-lim, lim], [-lim, lim], "k--", lw=1)
    ax.set_xlabel("Measured battery power (kW)")
    ax.set_ylabel("Simulated battery power (kW)")
    ax.set_title("Parity plot, validation drives")
    ax.set_aspect("equal")
    ax.grid(True, alpha=0.3)
    ax.legend(markerscale=6, fontsize=8)
    fig.tight_layout()
    fig.savefig(out, dpi=140)
    plt.close(fig)
    return out


def _plot_energy_errors(before: pd.DataFrame, after: pd.DataFrame, out: Path) -> Path:
    fig, ax = plt.subplots(figsize=(9, 4))
    x = np.arange(len(before))
    ax.bar(x - 0.2, before["energy_error_pct"], 0.4, label="initial model")
    ax.bar(x + 0.2, after["energy_error_pct"], 0.4, label="calibrated model")
    ax.axhline(0, color="k", lw=0.8)
    ax.set_xticks(x, [f"{n}\n{a:.0f} degC" for n, a in zip(before["drive"], before["ambient_c"], strict=True)],
                  fontsize=8)  # fmt: skip
    ax.set_ylabel("Trip energy error (%)")
    ax.set_title("Trip energy error per drive (validation set)")
    ax.legend()
    ax.grid(True, axis="y", alpha=0.3)
    fig.tight_layout()
    fig.savefig(out, dpi=140)
    plt.close(fig)
    return out


def _md_table(df: pd.DataFrame, floatfmt: str = ".4g") -> str:
    cols = list(df.columns)
    lines = ["| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)]
    for _, row in df.iterrows():
        cells = [format(v, floatfmt) if isinstance(v, float) else str(v) for v in row]
        lines.append("| " + " | ".join(cells) + " |")
    return "\n".join(lines)


def run_validation(
    p: ModelParams,
    config_path: Path,
    drives: list[MeasuredDrive],
    out_dir: Path,
    n_train: int,
    title: str = "Calibration and validation report",
    data_note: str = "",
    truth: dict[str, float] | None = None,
) -> tuple[CalibrationResult, pd.DataFrame, pd.DataFrame]:
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    train, val = drives[:n_train], drives[n_train:]
    if not val:
        raise ValueError("need at least one validation drive")

    before = evaluate(p, val)
    cal = calibrate(p, train, DEFAULT_PARAMS)
    after = evaluate(cal.params, val)
    train_after = evaluate(cal.params, train)

    keys = [c.key for c in DEFAULT_PARAMS]
    cfg_out = write_calibrated_config(
        config_path, out_dir / "calibrated_vehicle.yaml", cal.params, keys
    )
    _plot_timeseries(p, cal.params, val[0], out_dir / "validation_timeseries.png")
    _plot_parity(cal.params, val, out_dir / "validation_parity.png")
    _plot_energy_errors(before, after, out_dir / "validation_energy_error.png")
    before.to_csv(out_dir / "metrics_before.csv", index=False)
    after.to_csv(out_dir / "metrics_after.csv", index=False)
    cal.table.to_csv(out_dir / "calibrated_parameters.csv", index=False)

    ptable = cal.table[["parameter", "initial", "estimate", "ci95_low", "ci95_high"]].copy()
    if truth:
        ptable["true value"] = [truth.get(k, np.nan) for k in ptable["parameter"]]
        ptable["inside 95% CI"] = [
            "yes" if lo <= truth.get(k, np.nan) <= hi else "no"
            for k, lo, hi in zip(
                ptable["parameter"], ptable["ci95_low"], ptable["ci95_high"], strict=True
            )
        ]
    cols = ["drive", "ambient_c", "distance_km", "rmse_kw", "bias_kw", "energy_error_pct",
            "consumption_meas_kwh_100km", "consumption_sim_kwh_100km"]  # fmt: skip
    summary = pd.DataFrame(
        {
            "set": [
                "validation, initial",
                "validation, calibrated",
                "calibration drives, calibrated",
            ],
            "mean RMSE (kW)": [
                before.rmse_kw.mean(),
                after.rmse_kw.mean(),
                train_after.rmse_kw.mean(),
            ],
            "mean abs. energy error (%)": [
                before.energy_error_pct.abs().mean(),
                after.energy_error_pct.abs().mean(),
                train_after.energy_error_pct.abs().mean(),
            ],
        }
    )

    md = f"""# {title}

{data_note}

* Model configuration: `{Path(config_path).name}`
* Calibration drives: {", ".join(d.name for d in train)}
* Validation drives (never seen by the calibration): {", ".join(d.name for d in val)}
* Calibrated configuration written to `{cfg_out.name}`

## Summary

{_md_table(summary, ".3g")}

## Calibrated parameters

Least squares on {cal.n_samples} power samples, {cal.n_evaluations} model evaluations.
RMSE on calibration drives: {cal.rmse_before_kw:.3f} kW before, {cal.rmse_after_kw:.3f} kW after.

{_md_table(ptable, ".4g")}

Confidence intervals assume independent residuals and are therefore optimistic.

### Parameter correlation

{_md_table(cal.correlation.reset_index().rename(columns={"index": "parameter"}), ".2f")}

A correlation close to -1 or +1 means the data cannot separate the two parameters well.

## Validation drives - initial model

{_md_table(before[cols], ".3g")}

## Validation drives - calibrated model

{_md_table(after[cols], ".3g")}

![time series](validation_timeseries.png)

![parity](validation_parity.png)

![energy error](validation_energy_error.png)
"""
    (out_dir / "report.md").write_text(md, encoding="utf-8")
    return cal, before, after


def run_synthetic_validation(p: ModelParams, config_path: Path, out_dir: Path) -> dict:
    """Full demonstration on synthetic data: case A (matched structure) and B (structural error)."""
    from evdynasim.measured import load_measured_csv
    from evdynasim.synthetic import (
        MOTOR_LOSS_FACTOR,
        STRUCTURAL_CHANGES,
        TRUTH_PARAMS,
        synthetic_dataset,
    )

    out_dir = Path(out_dir)
    results = {}
    cases = {
        "A_matched_structure": (False, "Case A: the hidden vehicle has the same model structure. "
                                       "The calibration should recover the true parameters."),
        "B_structural_error": (True, "Case B: the hidden vehicle also has a rotating mass factor of "
                                     f"{STRUCTURAL_CHANGES['body.rotating_mass_factor']} (model: "
                                     f"{p.body.rotating_mass_factor}) and {MOTOR_LOSS_FACTOR:.2f}x the "
                                     "motor losses of the map. The calibration cannot estimate these, "
                                     "so the estimated parameters absorb the error and become "
                                     "effective values."),
    }  # fmt: skip
    for name, (structural, note) in cases.items():
        case_dir = out_dir / name
        data_dir = case_dir / "data"
        data_dir.mkdir(parents=True, exist_ok=True)
        drives = synthetic_dataset(p, 8, structural=structural)
        # round trip through CSV: exercises the same import path real data uses
        for d in drives:
            d.to_csv(data_dir / f"{d.name}.csv")
        drives = [load_measured_csv(data_dir / f"{d.name}.csv") for d in drives]
        warning = (
            "> **Synthetic data.** These drives were generated by simulating a hidden "
            "vehicle with known parameters and adding sensor noise. They are not "
            "measurements. They test the calibration and validation pipeline with a known answer.\n\n"
            + note
        )
        results[name] = run_validation(
            p, config_path, drives, case_dir, n_train=5,
            title=f"Calibration and validation - {name.replace('_', ' ')}",
            data_note=warning, truth=TRUTH_PARAMS,
        )  # fmt: skip
    return results
